"use client";

import { cn } from "@/lib/utils";
import React, { useEffect, useState } from "react";

// ==========================================
// 1. PAGE SHELL — aurora backdrop + bento grid
// ==========================================
export interface ProfilePageProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Three colours washed behind the glass, top-left / top-right / bottom.
   * Any CSS colour. The defaults are violet, sky and peach.
   */
  aurora?: [string, string, string];
}

export function ProfilePage({
  className,
  children,
  aurora = ["#a78bfa", "#7dd3fc", "#fdba74"],
  ...props
}: ProfilePageProps) {
  return (
    <div
      className={cn(
        "relative isolate w-full overflow-hidden bg-[#f5f5f7] text-[#1d1d1f] dark:bg-[#0b0b0f] dark:text-[#f5f5f7]",
        className,
      )}
      {...props}
    >
      {/* The blobs are what the glass blurs. They sit still — the only thing
          that moves on this page is the live marker on the dial. */}
      <div aria-hidden className="pointer-events-none absolute inset-0 -z-10">
        <span
          style={{ background: aurora[0] }}
          className="absolute -left-32 -top-32 size-[30rem] rounded-full opacity-60 blur-3xl dark:opacity-25"
        />
        <span
          style={{ background: aurora[1] }}
          className="absolute -right-24 top-16 size-[26rem] rounded-full opacity-60 blur-3xl dark:opacity-25"
        />
        <span
          style={{ background: aurora[2] }}
          className="absolute -bottom-40 left-1/3 size-[30rem] rounded-full opacity-50 blur-3xl dark:opacity-20"
        />
      </div>

      <div className="grid gap-4 p-4 sm:p-6 md:grid-cols-6 lg:grid-cols-12">
        {children}
      </div>
    </div>
  );
}

// ==========================================
// 2. GLASS PANEL — one recipe, four shapes
// ==========================================
export type GlassShape = "slab" | "tile" | "disc" | "capsule";

const SHAPES: Record<GlassShape, string> = {
  /** Hero-level surface. */
  slab: "rounded-[32px]",
  /** Everyday content tile. */
  tile: "rounded-3xl",
  /** A circle — for a single number or an icon. */
  disc: "aspect-square rounded-full",
  /** Chips, action bars, anything one line tall. */
  capsule: "rounded-full",
};

export interface GlassPanelProps extends React.HTMLAttributes<HTMLDivElement> {
  shape?: GlassShape;
  /** Lifts on hover and shows a pointer — for panels that open something. */
  interactive?: boolean;
}

export function GlassPanel({
  shape = "tile",
  interactive = false,
  className,
  children,
  ...props
}: GlassPanelProps) {
  return (
    <div
      className={cn(
        "relative border border-white/70 bg-white/55 shadow-[inset_0_1px_0_rgba(255,255,255,0.75),0_24px_48px_-28px_rgba(15,23,42,0.35)] backdrop-blur-2xl",
        "dark:border-white/10 dark:bg-white/[0.06] dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.08),0_24px_48px_-28px_rgba(0,0,0,0.9)]",
        SHAPES[shape],
        interactive &&
          "cursor-pointer transition-[transform,background-color] duration-200 hover:-translate-y-0.5 hover:bg-white/70 motion-reduce:transition-none motion-reduce:hover:translate-y-0 dark:hover:bg-white/[0.09]",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

// ==========================================
// 3. LOCAL TIME — hour-of-day in someone else's zone
// ==========================================
export interface LocalTime {
  /** Hour of day with minutes as a fraction, e.g. 14.5 for 14:30. */
  hour: number;
  /** Readable clock in that zone, e.g. "2:30 PM". */
  label: string;
}

/**
 * Reads the clock in `timeZone` every 30 seconds. Returns `null` until the
 * first read so server and client render the same thing.
 */
export function useLocalTime(timeZone: string): LocalTime | null {
  const [time, setTime] = useState<LocalTime | null>(null);

  useEffect(() => {
    const read = () => {
      const now = new Date();
      const parts = new Intl.DateTimeFormat("en-US", {
        timeZone,
        hour: "numeric",
        minute: "numeric",
        hour12: false,
      }).formatToParts(now);
      const h = Number(parts.find((p) => p.type === "hour")?.value ?? 0) % 24;
      const m = Number(parts.find((p) => p.type === "minute")?.value ?? 0);
      const label = new Intl.DateTimeFormat("en-US", {
        timeZone,
        hour: "numeric",
        minute: "2-digit",
      }).format(now);
      setTime({ hour: h + m / 60, label });
    };
    read();
    const id = setInterval(read, 30_000);
    return () => clearInterval(id);
  }, [timeZone]);

  return time;
}

// ==========================================
// 4. WORKDAY DIAL — 24 hours on a ring
// ==========================================
export interface WorkdayDialProps {
  /** IANA zone the person works in, e.g. "Asia/Dhaka". */
  timeZone: string;
  /** Working window in that zone, hours 0–24. */
  start: number;
  end: number;
  /** Short name shown under the clock, e.g. "Dhaka". */
  place: string;
  /** Person's first name, for the accessible description. */
  name: string;
  className?: string;
}

const R = 42;
const CIRCUMFERENCE = 2 * Math.PI * R;

/** Point on the ring for an hour of the day. The svg is rotated -90°, so
 *  angle 0 lands at the top — midnight. */
const pointAt = (hour: number) => {
  const a = (hour / 24) * Math.PI * 2;
  return { x: 50 + R * Math.cos(a), y: 50 + R * Math.sin(a) };
};

export function WorkdayDial({
  timeZone,
  start,
  end,
  place,
  name,
  className,
}: WorkdayDialProps) {
  const time = useLocalTime(timeZone);
  const working = time !== null && time.hour >= start && time.hour < end;
  const marker = time ? pointAt(time.hour) : null;

  const pad = (h: number) => `${String(h).padStart(2, "0")}:00`;
  const description = time
    ? `It is ${time.label} in ${place}. ${name} works ${pad(start)} to ${pad(end)}${working ? " and is working now." : "."}`
    : `${name} works ${pad(start)} to ${pad(end)} ${place} time.`;

  return (
    <div
      role="img"
      aria-label={description}
      className={cn("relative mx-auto aspect-square w-full max-w-[220px]", className)}
    >
      <svg viewBox="0 0 100 100" className="size-full -rotate-90">
        {/* Full day */}
        <circle
          cx="50"
          cy="50"
          r={R}
          fill="none"
          strokeWidth="6"
          className="stroke-black/[0.07] dark:stroke-white/10"
        />
        {/* Working window */}
        <circle
          cx="50"
          cy="50"
          r={R}
          fill="none"
          strokeWidth="6"
          strokeLinecap="round"
          strokeDasharray={`${(CIRCUMFERENCE * (end - start)) / 24} ${CIRCUMFERENCE}`}
          strokeDashoffset={-(CIRCUMFERENCE * start) / 24}
          className="stroke-violet-600 dark:stroke-violet-400"
        />
        {/* Six-hour ticks, outside the ring */}
        {[0, 6, 12, 18].map((h) => {
          const a = (h / 24) * Math.PI * 2;
          return (
            <line
              key={h}
              x1={50 + 47.5 * Math.cos(a)}
              y1={50 + 47.5 * Math.sin(a)}
              x2={50 + 50 * Math.cos(a)}
              y2={50 + 50 * Math.sin(a)}
              strokeWidth="1.5"
              strokeLinecap="round"
              className="stroke-black/25 dark:stroke-white/30"
            />
          );
        })}
        {/* Live marker */}
        {marker && (
          <g className="transition-transform duration-700 motion-reduce:transition-none">
            <circle
              cx={marker.x}
              cy={marker.y}
              r="5"
              className="fill-white dark:fill-[#0b0b0f]"
            />
            <circle
              cx={marker.x}
              cy={marker.y}
              r="3"
              className={cn(
                working
                  ? "fill-violet-600 dark:fill-violet-400"
                  : "fill-zinc-400 dark:fill-zinc-500",
              )}
            />
          </g>
        )}
      </svg>

      <div className="absolute inset-0 grid place-items-center text-center">
        <div>
          <p className="text-3xl font-semibold tabular-nums tracking-tight">
            {time ? time.label : "--:--"}
          </p>
          <p className="mt-0.5 text-sm text-black/60 dark:text-white/60">{place}</p>
          <p
            className={cn(
              "mt-2 text-xs font-medium",
              working
                ? "text-violet-700 dark:text-violet-300"
                : "text-black/50 dark:text-white/50",
            )}
          >
            {working ? "Working now" : "Off hours"}
          </p>
        </div>
      </div>
    </div>
  );
}
